    19	    public void sendConfirmationEmail(Reservation reservation) {
    20	        String subject = "Reserva confirmada - Pousada Maré Alta";
    21	        String body = buildConfirmationEmail(reservation);
    22	
    23	        Message message = new Message(MessageChannel.EMAIL, reservation.getGuestEmail(), subject, body);
    24	
    25	        try {
    26	            messageRepository.save(message);
    27	        } catch (SQLException e) {
    28	            throw new RuntimeException("Error sending message", e);
    29	        }
    30	    }
    31	
    32	    private String buildConfirmationEmail(Reservation reservation) {
    33	        StringBuilder sb = new StringBuilder();
    34	        sb.append("Olá, ").append(reservation.getGuestName()).append("!\n\n");
    35	        sb.append("Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n");
    36	        sb.append(buildReceipt(reservation));
    37	        sb.append("\n\nA entrada é a partir das 14h, e a saída, até as 12h.\n");
    38	        sb.append("Até breve!");
    39	        return sb.toString();
    40	    }
    41	
    42	    private String buildReceipt(Reservation reservation) {
    43	        StringBuilder sb = new StringBuilder();
    44	        sb.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
    45	        sb.append("Hóspede: ").append(reservation.getGuestName())
    46	          .append(" (CPF ").append(formatCpf(reservation.getGuestCpf())).append(")\n");
    47	        sb.append("Quarto: ").append(reservation.getRoomNumber())
    48	          .append(" (").append(reservation.getRoomType().name()).append(")\n");
    49	        sb.append("Entrada: ").append(formatDate(reservation.getCheckIn()))
    50	          .append(" | Saída: ").append(formatDate(reservation.getCheckOut()))
    51	          .append(" | ").append(reservation.getNights())
    52	          .append(reservation.getNights() == 1 ? " diária" : " diárias").append("\n");
    53	        sb.append("Diárias: R$ ").append(formatMoney(reservation.getSubtotal())).append("\n");
    54	
    55	        if (reservation.getDiscount().compareTo(java.math.BigDecimal.ZERO) > 0) {
    56	            sb.append("Desconto: R$ ").append(formatMoney(reservation.getDiscount())).append("\n");
    57	        }
    58	
    59	        sb.append("Total: R$ ").append(formatMoney(reservation.getTotal()));
    60	        return sb.toString();
    61	    }
