    63	    private String formatCpf(String cpf) {
    64	        if (cpf.length() == 11) {
    65	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
    66	                   cpf.substring(6, 9) + "-" + cpf.substring(9);
    67	        }
    68	        return cpf;
