    43	        StringBuilder sb = new StringBuilder();
    44	        sb.append("reservation,room,check_in,check_out,status,amount\n");
    45	
    46	        BigDecimal total = BigDecimal.ZERO;
    47	
    48	        for (Reservation reservation : reservations) {
    49	            BigDecimal amount = reservation.getRevenueAmount();
    50	
    51	            sb.append(reservation.getId()).append(",");
    52	            sb.append(reservation.getRoomNumber()).append(",");
    53	            sb.append(formatDateCsv(reservation.getCheckIn())).append(",");
    54	            sb.append(formatDateCsv(reservation.getCheckOut())).append(",");
    55	            sb.append(reservation.getStatus().name()).append(",");
    56	            sb.append(formatMoneyCsv(amount)).append("\n");
    57	
    58	            total = total.add(amount);
    59	        }
    60	
    61	        sb.append("total,").append(formatMoneyCsv(total));
    62	
    63	        return sb.toString();
