    26	
    27	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
    28	                                        LocalDate checkIn, LocalDate checkOut, int guests, String ratePlan, String companyCode) {
    29	        if (guests < 1) {
    30	            throw new InvalidRequestException("At least one guest is required");
    31	        }
    32	
    33	        if (!checkOut.isAfter(checkIn)) {
    34	            throw new InvalidRequestException("Check-out must be after check-in");
    35	        }
    36	
    37	        Room room = roomService.getRoomByNumber(roomNumber);
    38	
    39	        if (guests > room.getCapacity()) {
    40	            throw new CapacityExceededException("Room capacity exceeded");
    41	        }
    42	
    43	        try {
    44	            List<Reservation> overlapping = reservationRepository.findOverlappingReservations(roomNumber, checkIn, checkOut);
    45	            if (!overlapping.isEmpty()) {
    46	                throw new RoomUnavailableException("Room is not available for the selected dates");
    47	            }
    48	
    49	            Reservation reservation = new Reservation(
    50	                null, roomNumber, room.getType(), guestName, guestEmail, guestCpf,
    51	                checkIn, checkOut, guests, ratePlan, companyCode
    52	            );
    53	
    54	            return reservationRepository.save(reservation);
    55	        } catch (SQLException e) {
    56	            throw new RuntimeException("Error creating reservation", e);
    57	        }
    58	    }
    59	
    60	    public Reservation getReservation(Long id) {
    61	        try {
    62	            return reservationRepository.findById(id)
    63	                .orElseThrow(() -> new ReservationNotFoundException("Reservation not found"));
    64	        } catch (SQLException e) {
    65	            throw new RuntimeException("Error fetching reservation", e);
    66	        }
