    55	            sb.append(reservation.getStatus().name()).append(",");
    56	            sb.append(formatMoneyCsv(amount)).append("\n");
    57	
    58	            total = total.add(amount);
    59	        }
    60	
    61	        sb.append("total,").append(formatMoneyCsv(total));
    62	
    63	        return sb.toString();
    64	    }
    65	
    66	    private String formatDateCsv(LocalDate date) {
    67	        return String.format("%04d-%02d-%02d", date.getYear(), date.getMonthValue(), date.getDayOfMonth());
    68	    }
    69	
    70	    private String formatMoneyCsv(BigDecimal amount) {
    71	        return amount.toString();
    72	    }
    73	}
