    10	public abstract class AbstractRatePlan implements RatePlan {
    11	
    12	    protected BigDecimal calculateStandardSubtotal(LocalDate checkIn, LocalDate checkOut, RoomType roomType) {
    13	        BigDecimal subtotal = BigDecimal.ZERO;
    14	        LocalDate currentDate = checkIn;
    15	
    16	        while (currentDate.isBefore(checkOut)) {
    17	            BigDecimal nightRate = roomType.getNightlyRate();
    18	
    19	            if (DateUtil.isHighSeason(currentDate)) {
    20	                nightRate = MoneyUtil.round(nightRate.multiply(new BigDecimal("1.20")));
    21	            } else {
    22	                nightRate = MoneyUtil.round(nightRate);
    23	            }
    24	
    25	            subtotal = subtotal.add(nightRate);
    26	            currentDate = currentDate.plusDays(1);
    27	        }
    28	
    29	        return MoneyUtil.round(subtotal);
    30	    }
    31	
    32	    protected long countNights(LocalDate checkIn, LocalDate checkOut) {
    33	        return DateUtil.countNights(checkIn, checkOut);
    34	    }
