   229	            rs.getString("guest_cpf"),
   230	            rs.getDate("check_in").toLocalDate(),
   231	            rs.getDate("check_out").toLocalDate(),
   232	            rs.getInt("guests"),
   233	            rs.getString("rate_plan"),
   234	            null
   235	        );
   236	
   237	        java.lang.reflect.Field statusField;
   238	        java.lang.reflect.Field amountPaidField;
   239	        java.lang.reflect.Field refundField;
   240	
   241	        try {
   242	            statusField = Reservation.class.getDeclaredField("status");
   243	            statusField.setAccessible(true);
   244	            statusField.set(reservation, ReservationStatus.valueOf(rs.getString("status")));
   245	
   246	            amountPaidField = Reservation.class.getDeclaredField("amountPaid");
   247	            amountPaidField.setAccessible(true);
   248	            amountPaidField.set(reservation, rs.getBigDecimal("amount_paid"));
   249	
   250	            refundField = Reservation.class.getDeclaredField("refund");
   251	            refundField.setAccessible(true);
   252	            BigDecimal refund = rs.getBigDecimal("refund");
   253	            refundField.set(reservation, refund);
   254	        } catch (Exception e) {
   255	            throw new RuntimeException("Error mapping reservation", e);
   256	        }
   257	
   258	        return reservation;
   259	    }
   260	}
